-- =============================================================================
-- SCRIPT DML: CARGA DE DATOS SIMULADOS (POSTGRESQL)
-- Volumen: >1000 filas en FACT_VENTAS. Periodo: Q1 y Q2 2026. Regiones: >3
-- =============================================================================

SET search_path TO dm_ventas;

-- =============================================================================
-- 1. POBLADO DE HECHOS PRINCIPALES: FACT_VENTAS
-- =============================================================================

-- 1. Deshabilitar temporalmente las reglas matemáticas
ALTER TABLE dm_ventas.FACT_VENTAS DROP CONSTRAINT chk_monto_bruto;
ALTER TABLE dm_ventas.FACT_VENTAS DROP CONSTRAINT chk_monto_neto;
ALTER TABLE dm_ventas.FACT_VENTAS DROP CONSTRAINT chk_costo_total;
ALTER TABLE dm_ventas.FACT_VENTAS DROP CONSTRAINT chk_margen_bruto;
ALTER TABLE dm_ventas.FACT_VENTAS DROP CONSTRAINT chk_margen_neto;

begin;

-- 2. CARGA DIMENSIONES (Omitiendo centinela -1 que ya existe)







-- 3. CARGA HECHOS


commit;

-- 4. Forzar el cuadre exacto de centavos usando el propio motor
UPDATE dm_ventas.FACT_VENTAS
SET monto_bruto = cantidad * precio_unitario,
    costo_total_real = cantidad * costo_unitario_real;

UPDATE dm_ventas.FACT_VENTAS
SET monto_neto_venta = monto_bruto - monto_descuento;

UPDATE dm_ventas.FACT_VENTAS
SET margen_bruto = monto_neto_venta - costo_total_real;

UPDATE dm_ventas.FACT_VENTAS
SET margen_neto_real = margen_bruto - monto_comision_marketplace;

-- 5. Reactivar los constraints (Ahora pasarán sin errores)
ALTER TABLE dm_ventas.FACT_VENTAS ADD CONSTRAINT chk_monto_bruto CHECK (monto_bruto = cantidad * precio_unitario);
ALTER TABLE dm_ventas.FACT_VENTAS ADD CONSTRAINT chk_monto_neto CHECK (monto_neto_venta = monto_bruto - monto_descuento);
ALTER TABLE dm_ventas.FACT_VENTAS ADD CONSTRAINT chk_costo_total CHECK (costo_total_real = cantidad * costo_unitario_real);
ALTER TABLE dm_ventas.FACT_VENTAS ADD CONSTRAINT chk_margen_bruto CHECK (margen_bruto = monto_neto_venta - costo_total_real);
ALTER TABLE dm_ventas.FACT_VENTAS ADD CONSTRAINT chk_margen_neto CHECK (margen_neto_real = margen_bruto - monto_comision_marketplace);

-- =============================================================================
-- 2. POBLADO DE HECHOS DE POSVENTA: FACT_DEVOLUCIONES
-- =============================================================================
-- Se insertan 150 eventos de devolución ligados atómicamente a las ventas previas
    tiempo_sk,
    producto_sk,
    sucursal_sk,
    cliente_sk,
    num_devolucion,
    ticket_venta_origen,
    linea_venta_origen,
    numero_serie,
    motivo_devolucion,
    cantidad_devuelta,
    monto_devolucion
)
SELECT 
    fv.tiempo_sk,
    fv.producto_sk,
    fv.sucursal_sk,
    fv.cliente_sk,
    'DEV-' || ROW_NUMBER() OVER (ORDER BY fv.num_ticket, fv.num_linea) AS num_devolucion,
    fv.num_ticket AS ticket_venta_origen,
    fv.num_linea AS linea_venta_origen,
    fv.numero_serie,
    'Devolución por defecto de fábrica / Mantenimiento' AS motivo_devolucion,
    1 AS cantidad_devuelta,
    ROUND((fv.monto_neto_venta * 0.15)::numeric, 2) AS monto_devolucion
FROM dm_ventas.FACT_VENTAS fv
WHERE fv.num_linea = 1
LIMIT 150;